body.en:
Fictional contract: values holds workspace, email and summary. On an invalid submit, values MUST stay unchanged, focus MUST move to the error summary, and each error MUST be linked to its field by id. Observed on the current build: pressing Enter on the empty form moves focus to the document body, wipes every typed value, and the screen reader announces a detached toast that is not linked to any input.
```tsx
import { useState } from 'react'

export function SupportForm() {
  const [values, setValues] = useState({ workspace: '', email: '', summary: '' })
  const [errors, setErrors] = useState<Record<string, string>>({})

  function onSubmit(e: React.FormEvent) {
    e.preventDefault()
    const next: Record<string, string> = {}
    if (!values.workspace) next.workspace = 'Workspace name is required'
    if (!values.email.includes('@')) next.email = 'Email is invalid'
    if (!values.summary) next.summary = 'Incident summary is required'
    setErrors(next)
    if (Object.keys(next).length) {
      document.body.focus()
      setValues({ workspace: '', email: '', summary: '' })
      return
    }
    alert('Submitted')
  }

  return (
    <form onSubmit={onSubmit}>
      <input name="workspace" placeholder="Workspace name" value={values.workspace} onChange={e => setValues({ ...values, [e.target.name]: e.target.value })} />
      <input name="email" placeholder="Contact email" value={values.email} onChange={e => setValues({ ...values, [e.target.name]: e.target.value })} />
      <input name="summary" placeholder="Incident summary" value={values.summary} onChange={e => setValues({ ...values, [e.target.name]: e.target.value })} />
      {errors.workspace && <div className="toast">{errors.workspace}</div>}
      {errors.email && <div className="toast">{errors.email}</div>}
      {errors.summary && <div className="toast">{errors.summary}</div>}
      <button type="submit">Submit</button>
    </form>
  )
}
```

