Fictional files index.html and form.js for the RelayDesk request form, simulated for this exercise. Fixed contract: the field ids stay displayName and contactEmail, the field error element ids stay displayName-error and contactEmail-error, the summary id is error-summary with tabindex=-1, and the confirmation element id is form-status. The shipped index.html has no element with id error-summary and neither input carries aria-describedby. form.js performs its DOM lookups at load time. Observed on the shipped build: focus lands on the document body and the typed values are erased.
```html
<form id="request-form" novalidate>
  <label for="displayName">Display name</label>
  <input id="displayName" name="displayName">
  <p id="displayName-error"></p>
  <label for="contactEmail">Contact email</label>
  <input id="contactEmail" name="contactEmail">
  <p id="contactEmail-error"></p>
  <button type="submit">Submit</button>
</form>
<p id="form-status"></p>
```
```js
const form = document.getElementById('request-form')
const displayName = document.getElementById('displayName')
const contactEmail = document.getElementById('contactEmail')
const status = document.getElementById('form-status')

function isValidEmail(value) {
  return value.includes('@')
}

form.addEventListener('submit', function (event) {
  event.preventDefault()
  const nameError = document.getElementById('displayName-error')
  const emailError = document.getElementById('contactEmail-error')
  nameError.textContent = ''
  emailError.textContent = ''

  let invalid = false
  if (displayName.value.trim() === '') {
    nameError.textContent = 'Display name is required.'
    invalid = true
  }
  if (!isValidEmail(contactEmail.value)) {
    emailError.textContent = 'Contact email is invalid.'
    invalid = true
  }

  if (invalid) {
    form.reset()
    document.activeElement.blur()
    return
  }

  status.textContent = 'Thanks, your request was recorded.'
})
```

