```ts
import { useEffect, useState } from 'react';

type Result = { id: string; title: string };
type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; items: Result[] }
  | { status: 'error'; message: string };

export function useSearch(query: string, search: (q: string) => Promise<Result[]>) {
  const [state, setState] = useState<State>({ status: 'idle' });

  useEffect(() => {
    if (query.trim() === '') {
      setState({ status: 'idle' });
      return;
    }
    setState({ status: 'loading' });
    search(query)
      .then((items) => setState({ status: 'success', items }))
      .catch((error) => setState({ status: 'error', message: String(error) }));
  }, [query, search]);

  return state;
}
```

Contract. Input query is a string. search(query) returns Promise<Result[]>. The latest query request owns the state. Any earlier request may resolve or reject later. Its settlement must be ignored.

