```ts
export async function submitCheckout(
  idempotencyKey: string,
  merchantId: string,
  basketId: string,
  items: Array<{ sku: string, qty: number }>
) {
  const body = JSON.stringify({ idempotencyKey, merchantId, basketId, items })
  const headers = { 'content-type': 'application/json' }
  const attempt = () => fetch('/api/checkout', { method: 'POST', headers, body })
  let res
  try {
    res = await attempt()
  } catch (err) {
    res = await attempt()
  }
  const data = await res.json()
