Simulated file: src/server/basket-route.ts and src/client/save-basket.ts. The route reads the version, updates items and reserves stock in separate steps. The client retries a 409 with the same stale expectedVersion.
```ts
app.patch('/api/baskets/:basketId', async (req, res) => {
  const { basketId } = req.params
  const { expectedVersion, items } = req.body
  const version = await getVersion(basketId)
  await updateItems(basketId, items)
  await reserveStock(items)
  await setVersion(basketId, version + 1)
  res.status(200).json({ basketId, version: version + 1, items })
})

export async function saveBasket(
  basketId: string,
  expectedVersion: number,
  items: Array<{ sku: string, qty: number }>
) {
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const res = await fetch(`/api/baskets/${basketId}`, {
      method: 'PATCH',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ expectedVersion, items })
    })
    if (res.status === 200) return await res.json()
    // defect: retries with the same stale expectedVersion
  }
  throw new Error('basket_update_failed')
}
```
Test observation: two concurrent PATCH requests with expectedVersion 3 both read version 3 before either write completes, both reserve stock, both set version 4, so one item update is lost and stock is reserved twice. The client then retries a 409 with the same stale expectedVersion.

