The following fictional TypeScript handler is under review. It is read-only and no code execution is required. items is the full synthetic collection of 120 documents. The contract requires page 1 to return the first page. A teammate observed page=1 and page=3 with pageSize=50. Review the boundary defect.

```ts
type PageResult = {
  items: string[]
  page: number
  pageSize: number
  total: number
  hasNext: boolean
}

export function getPage(
  items: string[],
  page: number,
  pageSize: number,
): PageResult | { error: string } {
  if (pageSize < 1 || pageSize > 100) {
    return { error: "invalid_paging" }
  }
  const start = page * pageSize
  const end = start + pageSize
  const slice = items.slice(start, end)
  return {
    items: slice,
    page,
    pageSize,
    total: items.length,
    hasNext: end < items.length,
  }
}
```

