The following fictional TypeScript handler is under review. It is read-only and no code execution is required. The contract requires idempotency key validation, payload comparison, and correct status codes. Review the boundary defect.

```ts
type Order = { id: string, amount: number, currency: string }

const orders = new Map<string, Order>()

export function createOrder(
  idempotencyKey: string,
  payload: { amount: number, currency: string }
): { status: number, body: any } {
  if (orders.has(idempotencyKey)) {
    return { status: 200, body: orders.get(idempotencyKey) }
  }
  const order = { id: `ord-${Date.now()}`, ...payload }
  orders.set(idempotencyKey, order)
